configuration.bicep:
resource vm 'Microsoft.Compute/virtualMachines@2024-03-01' = {
  name: 'vm1'
  location: location
  zones: [ '1' ]
  properties: {
    hardwareProfile: { vmSize: 'Standard_D2s_v5' }
    osProfile: { computerName: 'vm1', adminUsername: 'azureuser', linuxConfiguration: { disablePasswordAuthentication: true, ssh: { publicKeys: [ { path: '/home/azureuser/.ssh/authorized_keys', keyData: sshKey } ] } } }
    storageProfile: { imageReference: { publisher: 'Canonical', offer: '0001-com-ubuntu-server-jammy', sku: '22_04-lts-gen2', version: 'latest' }, osDisk: { createOption: 'FromImage', managedDisk: { storageAccountType: 'Premium_LRS' } } }
    networkProfile: { networkInterfaces: [ { id: nicId } ] }
  }
}
param location string = resourceGroup().location
param sshKey string
param nicId string
